  f('B.5','Resistance',t`R=\frac{V}{I}`,'Defines resistance at an operating point. Ohm’s law further requires V proportional to I at constant physical conditions.', t`R|resistance|Ω;V|potential difference across component|V;I|current through component|A`,9);
  f('B.5','Resistivity',t`\rho=\frac{RA}{L}`,'For a uniform conductor. Here ρ is electrical resistivity, not mass density.', t`\rho|resistivity|Ω m;R|resistance|Ω;A|cross-sectional area|m²;L|conductor length|m`,9);
  f('B.5','Electrical power',t`P=VI=I^2R=\frac{V^2}{R}`,'Use the voltage across and current through the same component. The last two forms follow from R = V/I.', t`P|electrical power|W;V|potential difference|V;I|current|A;R|resistance|Ω`,9);
  f('B.5','Series circuits',t`I=I_1=I_2=\cdots,\quad V=V_1+V_2+\cdots,\quad R_{\rm s}=R_1+R_2+\cdots`,'A series path carries the same current through every component. Potential differences add.', t`I,I_1,I_2|total and component currents|A;V,V_1,V_2|supply and component potential differences|V;R_{\rm s}|equivalent series resistance|Ω;R_1,R_2|component resistances|Ω`,9);
  f('B.5','Parallel circuits',t`I=I_1+I_2+\cdots,\quad V=V_1=V_2=\cdots,\quad \frac1{R_{\rm p}}=\frac1{R_1}+\frac1{R_2}+\cdots`,'Parallel branches share the same potential difference; current splits at junctions.', t`I,I_1,I_2|total and branch currents|A;V,V_1,V_2|supply and branch potential differences|V;R_{\rm p}|equivalent parallel resistance|Ω;R_1,R_2|branch resistances|Ω`,9);
  f('B.5','Cell with internal resistance',t`\varepsilon=I(R+r)`,'For a cell delivering current through an external resistance. Its terminal p.d. is ε − Ir.', t`\varepsilon|electromotive force, energy supplied per charge|V;I|current|A;R|external resistance|Ω;r|internal resistance|Ω`,9);
