  f('C.1','Mass–spring period',t`T=2\pi\sqrt{\frac{m}{k}}`,'Ideal mass on a spring with negligible spring mass and no damping. Independent of amplitude within the Hooke’s-law regime.', t`T|period|s;m|oscillating mass|kg;k|spring constant|N m⁻¹`,10);
